require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

async function testDatabaseConnection() {
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  try {
    await client.connect();
    console.log('Database connection successful');
  } catch (err) {
    console.error('Database connection failed:', err.message);
  } finally {
    await client.end();
  }
}

async function testAWSKeys() {
  AWS.config.update({
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  });

  const s3 = new AWS.S3();
  try {
    await s3.listBuckets().promise();
    console.log('AWS keys are valid');
  } catch (err) {
    console.error('AWS keys are invalid:', err.message);
  }
}

async function testAnthropicAPIKey() {
  try {
    const response = await axios.get('https://api.anthropic.com/v1/test', {
      headers: { 'Authorization': `Bearer ${process.env.ANTHROPIC_API_KEY}` },
    });
    console.log('Anthropic API key is valid:', response.data);
  } catch (err) {
    console.error('Anthropic API key is invalid:', err.message);
  }
}

async function testStripeAPIKey() {
  try {
    const response = await axios.get('https://api.stripe.com/v1/charges', {
      auth: { username: process.env.STRIPE_SECRET_KEY, password: '' },
    });
    console.log('Stripe API key is valid:', response.data);
  } catch (err) {
    console.error('Stripe API key is invalid:', err.message);
  }
}

(async () => {
  await testDatabaseConnection();
  await testAWSKeys();
  await testAnthropicAPIKey();
  await testStripeAPIKey();
})();

