const { Client } = require('pg');
const AWS = require('aws-sdk');
const axios = require('axios');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

async function testDatabaseConnection() {
  const client = new Client({
    connectionString: process.env.DATABASE_URL,
  });
  try {
    await client.connect();
    console.log('Database connection successful');
  } catch (err) {
    console.error('Database connection failed:', err);
  } finally {
    await client.end();
  }
}

async function testAWSCredentials() {
  AWS.config.update({
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  });
  const s3 = new AWS.S3();
  try {
    const buckets = await s3.listBuckets().promise();
    console.log('AWS S3 Buckets:', buckets);
  } catch (err) {
    console.error('AWS credentials are invalid:', err);
  }
}

async function testAnthropicAPIKey() {
  try {
    const response = await axios.get('https://api.anthropic.com/v1/test', {
      headers: { 'Authorization': `Bearer ${process.env.ANTHROPIC_API_KEY}` },
    });
    console.log('Anthropic API response:', response.data);
  } catch (err) {
    console.error('Anthropic API key is invalid:', err);
  }
}

async function testStripeAPIKey() {
  try {
    const response = await axios.get('https://api.stripe.com/v1/customers', {
      headers: { 'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}` },
    });
    console.log('Stripe API response:', response.data);
  } catch (err) {
    console.error('Stripe API key is invalid:', err);
  }
}

(async () => {
  await testDatabaseConnection();
  await testAWSCredentials();
  await testAnthropicAPIKey();
  await testStripeAPIKey();
})();

